#if UNITY_EDITOR
using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;
using UnityEngine;using UnityEngine.UI;
using HeartOfTheRain.App.Profile;using HeartOfTheRain.App.Home;using HeartOfTheRain.App.FirstStart;using HeartOfTheRain.App.Localization;
namespace HeartOfTheRain.Verification {
    public sealed class BackendGiftUIProbe:MonoBehaviour {
        public const string RequestName="HOTR_RunBackendGiftUI";
        [Serializable] public sealed class Request {public string runId,mode;}
        [Serializable] sealed class Credential {public string playerId,token;}
        [Serializable] sealed class Bootstrap {public string origin;public Credential ui;}
        [Serializable] public sealed class Report {
            public string utc,status="RUNNING",unity,mode,scope="Native Unity Play Mode, real Home/Daily Gift button dispatch and actual HTTP to a separate local server. Isolated account/file profile. Delays/503/lost confirmation are explicit fixture-only faults. Camera-rendered runtime UGUI frames, not device screenshots or FPS certification.";
            public int checks,width,height,framesDuringDelay;public List<string> passed=new List<string>(),frames=new List<string>(),failures=new List<string>();
            public float uiScale,contentHeight,viewportHeight;
        }
        public Report report;string root,controls,mode;PlayerProfileHost host;HomePage home;DailyGiftPage page;BackendClient client;int locale;float deadline;
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void Boot(){
            string marker=Path.Combine(Application.persistentDataPath,RequestName);if(!File.Exists(marker))return;var request=JsonUtility.FromJson<Request>(File.ReadAllText(marker));File.Delete(marker);Guid id;if(request==null||!Guid.TryParseExact(request.runId,"N",out id))throw new InvalidOperationException("Invalid backend UI fixture");
            string path=Environment.GetEnvironmentVariable("HOTR_BACKEND_VERIFICATION_CONFIG");if(string.IsNullOrEmpty(path)||!Path.GetFullPath(path).StartsWith(Path.GetFullPath("../.verification-cache/Backend/"),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Explicit ignored backend fixture required");var config=JsonUtility.FromJson<Bootstrap>(File.ReadAllText(path));if(config?.ui==null)throw new InvalidOperationException("Isolated UI account required");
            if(request.mode!="Play"&&request.mode!="Restart")throw new InvalidOperationException("Invalid UI fixture mode");var first=FindFirstObjectByType<FirstStartPage>();first.reviewAlways=true;var probe=new GameObject("Opt-in backend Daily Gift UI verification").AddComponent<BackendGiftUIProbe>();probe.mode=request.mode;probe.root=Path.GetFullPath("../.verification-cache/BackendGiftUI/U-"+request.runId.Substring(0,8));probe.controls=Path.GetDirectoryName(path);probe.home=first.home;probe.host=first.home.gameObject.AddComponent<PlayerProfileHost>();
            probe.host.VerificationRepository=new FileProfileRepository(Path.Combine(probe.root,"Client"),()=>{var p=PlayerProfile.New(first.home.GetComponent<HeartOfTheRain.App.PreLevel.HomeLevelFlow>().assets.initialStock);p.playerId=config.ui.playerId;return p;});probe.client=new BackendClient(config.origin,config.ui.token,true);probe.host.VerificationBackendClient=probe.client;
        }
        IEnumerator Start(){
            report=new Report{utc=DateTime.UtcNow.ToString("o"),unity=Application.unityVersion,mode=mode,width=Screen.width,height=Screen.height};Directory.CreateDirectory(root);Application.logMessageReceived+=Log;locale=GameLocale.Current;deadline=Time.realtimeSinceStartup+150;
            yield return Wait(()=>FindFirstObjectByType<FirstStartPage>().IsVisible);var first=FindFirstObjectByType<FirstStartPage>();first.Request("skip");first.Request("skip");GameLocale.Select(0);yield return null;
            page=home.GetComponent<DailyGiftPage>();Check(host.Ready&&!host.IsTransient&&host.BackendGifts!=null,"Real Home host uses isolated file profile and explicit remote gift session");Check(!host.Gifts.IsDevelopment&&host.Gifts.Offer()==null,"Local gift authority cannot grant in the remote review profile");Check(Screen.height>Screen.width,"Native Game View uses a portrait viewport");
            if(mode=="Restart"){
                home.SetUIScale(1);Check(host.Service.Read().coins==1300&&host.Service.Read().giftClaims==1&&host.Service.Read().pendingGift==null,"Native process restart preserves one confirmed UI gift");ClickHome();yield return Wait(()=>!page.IsNetworkBusy);Check(ClaimButton().interactable&&Label("claim-label")==DailyGiftDesignText.T("done"),"Restarted page uses actual server claimed state");page.Request("claim");yield return Wait(()=>!page.IsNetworkBusy);Check(host.Service.Read().coins==1300&&host.Service.Read().giftClaims==1,"Restarted UI cannot repeat the credit");var scroll=page.transform.Find("Daily Gift Canvas").GetComponentInChildren<ScrollRect>();report.uiScale=home.CurrentUIScale;report.contentHeight=scroll.content.rect.height;report.viewportHeight=scroll.viewport.rect.height;Check(scroll&&scroll.vertical,"Short portrait viewport at 100 percent UI scale exposes native vertical scrolling");scroll.verticalNormalizedPosition=0;yield return null;yield return null;Capture("Restart_ShortPhone_scrolled_en");page.Hide();Finish(null);yield break;
            }
            Flag("delay-offer");ClickHome();Check(page.IsVisible&&page.IsNetworkBusy,"Home shortcut opens immediately while real HTTP is pending");yield return null;yield return null;Check(Label("claim-label")==DailyGiftDesignText.T("claim")&&!ClaimButton().interactable,"Loading state disables duplicate claim input");Capture("Loading_en");
            int frame=Time.frameCount;page.Request("close");Check(!page.IsVisible&&page.IsNetworkBusy,"Close responds during an outstanding offer request");page.Show();Check(page.IsVisible&&page.IsNetworkBusy,"Reopen joins the outstanding request without starting another operation");
            int fatalRetries=0;page.ShowError(()=>{fatalRetries++;page.Show();});yield return Wait(()=>!page.IsNetworkBusy);report.framesDuringDelay=Time.frameCount-frame;Check(report.framesDuringDelay>=3,"HTTP wait yields across PlayerLoop updates rather than synchronously waiting");Check(Label("title")==DailyGiftText.T("Please try again")&&!page.GetComponentsInChildren<HomeControlLabel>().Any(l=>l.action=="close"),"Background completion cannot replace a fatal save dialog");Capture("Save_Dialog_en");ClickClaim();yield return Wait(()=>!page.IsNetworkBusy);Check(fatalRetries==1,"Original save retry callback survives the background response");Check(Label("claim-label")==DailyGiftDesignText.T("claim"),"Completed offer enables one claim");Check(host.Service.Read().coins==1250&&host.Service.Read().pendingGift==null,"Offer retrieval cannot grant or reserve a reward");Capture("Ready_en");
            page.Hide();Flag("offline-offer");page.Show();yield return Wait(()=>!page.IsNetworkBusy);Check(Label("status")==DailyGiftText.T("Your gift could not be confirmed. Please try again."),"Actual HTTP 503 shows a retry state without raw server errors");Check(ClaimButton().interactable,"Unavailable offer has an enabled retry");Capture("Unavailable_en");ClickClaim();yield return Wait(()=>!page.IsNetworkBusy);Check(Label("claim-label")==DailyGiftDesignText.T("claim")&&host.Service.Read().pendingGift==null&&host.Service.Read().coins==1250,"Offer retry fetches availability without accidentally claiming");
            Flag("delay-claim");Flag("drop-claim");ClickClaim();page.Request("claim");yield return Wait(()=>host.Service.Read().pendingGift!=null);string pending=host.Service.Read().pendingGift.requestId;Check(page.IsNetworkBusy&&!ClaimButton().interactable,"Claim request saves intent and rejects duplicate interaction");Check(host.Service.Read().coins==1250,"Reward is not credited before server confirmation");Capture("Claiming_en");page.Request("close");Check(!page.IsVisible&&page.IsNetworkBusy,"Claim can be closed while its durable intent remains in flight");var works=home.GetComponent<WellworksPage>();works.Show();yield return Wait(()=>!page.IsNetworkBusy);Check(works.IsVisible&&!page.IsVisible,"Late response cannot reopen Daily Gift over another page");var saved=host.Service.Read();Check(saved.pendingGift?.requestId==pending&&saved.giftClaims==0&&saved.coins==1250,"Lost server confirmation preserves the original uncredited intent");BackendResult<BackendAccount> account=null;yield return client.Account(value=>account=value);Check(account.ok&&account.value.rewardTotals[0]==50,"Real backend has exactly one committed gift despite lost confirmation");works.Hide();page.Show();yield return Wait(()=>!page.IsNetworkBusy);Check(Label("claim-label")==DailyGiftDesignText.T("retry"),"Reopened pending claim offers explicit recovery");Capture("Pending_Recovery_en");
            ClickClaim();page.Request("claim");yield return Wait(()=>!page.IsNetworkBusy);saved=host.Service.Read();Check(saved.coins==1300&&saved.giftClaims==1&&saved.pendingGift==null,"UI retry reconciles the original receipt into one durable local credit");Check(home.State.coins==1300,"Home counter reads the saved reward before cosmetic reveal");Check(Label("status")==DailyGiftDesignText.T("nextGift")&&Label("claim-label")==DailyGiftDesignText.T("done")&&ClaimButton().interactable,"Confirmed result immediately shows claimed state without a second network refresh");
            for(int language=0;language<5;language++){GameLocale.Select(language);yield return null;Capture("Saved_"+new[]{"en","es","fr","de","ru"}[language]);Check(Label("claim-label")==DailyGiftDesignText.T("done"),"Claimed label follows locale "+language);}
            page.Request("close");Check(!page.IsVisible,"Completed gift modal closes normally");page.Show();yield return Wait(()=>!page.IsNetworkBusy);page.Request("claim");yield return Wait(()=>!page.IsNetworkBusy);Check(host.Service.Read().coins==1300&&host.Service.Read().giftClaims==1,"Reopen and repeated claim cannot credit a second gift");yield return client.Account(value=>account=value);Check(account.ok&&account.value.rewardTotals[0]==50,"Server ledger remains one gift after every UI retry");BackendResult<BackendReceipts> receipts=null;yield return client.Receipts(0,value=>receipts=value);Check(receipts.ok&&receipts.value.receipts.Length==1,"One server receipt backs the UI result");
            page.Hide();Finish(null);
        }
        void Flag(string name)=>File.WriteAllText(Path.Combine(controls,name+".once"),"explicit UI verification fault");
        void ClickHome(){var control=home.GetComponentsInChildren<HomeControlLabel>().First(l=>l.action=="daily");var button=control.GetComponent<Button>();Check(button&&button.interactable,"Home Daily Gift button is interactable");button.onClick.Invoke();}
        Button ClaimButton()=>page.GetComponentsInChildren<HomeControlLabel>().First(l=>l.name=="claim").GetComponent<Button>();
        void ClickClaim(){var button=ClaimButton();Check(button.interactable,"Daily Gift primary button accepts this interaction");button.onClick.Invoke();}
        string Label(string name)=>page.GetComponentsInChildren<Text>().First(t=>t.name==name).text;
        IEnumerator Wait(Func<bool> ready){while(!ready()){if(Time.realtimeSinceStartup>deadline)throw new TimeoutException("Backend gift UI timed out");yield return null;}}
        void Check(bool value,string name){report.checks++;if(!value)throw new InvalidOperationException(name);report.passed.Add(name);}
        void Capture(string name){
            var canvases=FindObjectsByType<Canvas>(UnityEngine.FindObjectsSortMode.InstanceID).Where(c=>c.isActiveAndEnabled&&c.renderMode==RenderMode.ScreenSpaceOverlay).ToArray();var cameras=canvases.Select(c=>c.worldCamera).ToArray();var distances=canvases.Select(c=>c.planeDistance).ToArray();var go=new GameObject("Native UI evidence camera");var camera=go.AddComponent<Camera>();camera.transform.position=new Vector3(-10000,0,-10);camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;var active=RenderTexture.active;var target=RenderTexture.GetTemporary(Screen.width,Screen.height,24,RenderTextureFormat.ARGB32);var pixels=new Texture2D(Screen.width,Screen.height,TextureFormat.RGBA32,false);
            try{camera.targetTexture=target;foreach(var canvas in canvases){canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;}Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;pixels.ReadPixels(new Rect(0,0,target.width,target.height),0,0);pixels.Apply();Check(pixels.GetPixels32().Count(c=>c.r>35||c.g>35||c.b>35)>10000,"Native runtime UGUI rendered "+name);File.WriteAllBytes(Path.Combine(root,name+".png"),pixels.EncodeToPNG());report.frames.Add(name+".png");}
            finally{for(int i=0;i<canvases.Length;i++){canvases[i].renderMode=RenderMode.ScreenSpaceOverlay;canvases[i].worldCamera=cameras[i];canvases[i].planeDistance=distances[i];}RenderTexture.active=active;RenderTexture.ReleaseTemporary(target);Destroy(pixels);Destroy(go);Canvas.ForceUpdateCanvases();}
        }
        void Log(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)Finish("Unexpected native error during UI verification");}
        void Update(){if(report!=null&&report.status=="RUNNING"&&Time.realtimeSinceStartup>deadline)Finish("Native UI timed out");}
        void Finish(string error){if(report.status!="RUNNING")return;Application.logMessageReceived-=Log;if(error!=null)report.failures.Add(error);report.status=error==null?"PASS_NATIVE_BACKEND_GIFT_UI":"FAIL_NATIVE_BACKEND_GIFT_UI";GameLocale.Select(locale);File.WriteAllText(Path.Combine(root,"Report.json"),JsonUtility.ToJson(report,true));}
        void OnDestroy(){Application.logMessageReceived-=Log;}
    }
}
#endif
